  ]) throws(() => satisfies('1.0.0', bad));
  throws(() => satisfies('1.0.0', 42));
  throws(() => satisfies(42, '1.0.0'));
});

test('frozen inputs work and are not mutated', () => {
  const a = Object.freeze('1.2.3-rc.1');
